        "_causal_conv1d_update_kernel": "@triton.jit\ndef _causal_conv1d_update_kernel(\n    # Pointers to matrices\n    x_ptr,  # (batch, dim, seqlen)\n    w_ptr,  # (dim, width)\n    bias_ptr,\n    conv_state_ptr,\n    cache_seqlens_ptr,  # circular buffer\n    conv_state_indices_ptr,\n    o_ptr,  # (batch, dim, seqlen)\n    # Matrix dimensions\n    batch: int,\n    dim: tl.constexpr,\n    seqlen: tl.constexpr,\n    state_len: tl.constexpr,\n    num_cache_lines: tl.constexpr,\n    # Strides\n    stride_x_seq: tl.constexpr,\n    stride_x_dim: tl.constexpr,\n    stride_x_token: tl.constexpr,\n    stride_w_dim: tl.constexpr,\n    stride_w_width: tl.constexpr,\n    stride_conv_state_seq: tl.constexpr,\n    stride_conv_state_dim: tl.constexpr,\n    stride_conv_state_tok: tl.constexpr,\n    stride_o_seq: tl.constexpr,\n    stride_o_dim: tl.constexpr,\n    stride_o_token: tl.constexpr,\n    # others\n    pad_slot_id: tl.constexpr,\n    # Meta-parameters\n    HAS_BIAS: tl.constexpr,\n    KERNEL_WIDTH: tl.constexpr,\n    SILU_ACTIVATION: tl.constexpr,\n    IS_CONTINUOUS_BATCHING: tl.constexpr,\n    NP2_STATELEN: tl.constexpr,\n    USE_PAD_SLOT: tl.constexpr,\n    BLOCK_N: tl.constexpr,\n):\n    # Each program handles one (batch, dim) pair\n    pid_b = tl.program_id(axis=0)\n    pid_d = tl.program_id(axis=1)\n    \n    # Handle conv_state_indices for continuous batching\n    if IS_CONTINUOUS_BATCHING:\n        conv_state_indices_ptr += pid_b\n        state_idx = tl.load(conv_state_indices_ptr).to(tl.int32)\n        # Skip padding slots\n        if USE_PAD_SLOT:\n            if state_idx == pad_slot_id:\n                return\n    else:\n        state_idx = pid_b\n    \n    # Compute base pointers for this (batch, dim) pair\n    x_base = pid_b * stride_x_seq + pid_d * stride_x_dim\n    w_base = pid_d * stride_w_dim\n    if HAS_BIAS:\n        bias_ptr += pid_d\n    conv_state_base = state_idx * stride_conv_state_seq + pid_d * stride_conv_state_dim\n    o_base = pid_b * stride_o_seq + pid_d * stride_o_dim\n    \n    # Load weight for this dimension (width elements)\n    w_offs = tl.arange(0, BLOCK_N)\n    w_mask = w_offs < KERNEL_WIDTH\n    w = tl.load(w_ptr + w_base + w_offs * stride_w_width, mask=w_mask, other=0.0).to(tl.float32)\n    \n    # Load bias\n    if HAS_BIAS:\n        bias = tl.load(bias_ptr).to(tl.float32)\n    else:\n        bias = 0.0\n    \n    # Load cache_seqlens if using circular buffer\n    use_circular = cache_seqlens_ptr is not None\n    if use_circular:\n        cache_seqlens_ptr += pid_b\n        cache_seqlen = tl.load(cache_seqlens_ptr).to(tl.int32)\n    else:\n        cache_seqlen = 0\n    \n    # Process each token in the sequence\n    for tok in range(seqlen):\n        # For causal conv1d: out[t] = sum_{i=0}^{width-1} x[t-i] * w[i]\n        # State contains x[t-width+1:t], so we need state[0:width-1] and current x\n        \n        # Load state elements (width-1 elements for the window before current token)\n        state_offs = tl.arange(0, BLOCK_N)\n        state_mask = state_offs < (KERNEL_WIDTH - 1)\n        \n        if use_circular:\n            # Circular buffer: load from conv_state with offset\n            # State positions: (cache_seqlen - (width-1) + i) % state_len for i in 0..width-2\n            load_indices = (cache_seqlen - (KERNEL_WIDTH - 1) + state_offs) % state_len\n            state_ptrs = conv_state_ptr + conv_state_base + load_indices * stride_conv_state_tok\n        else:\n            # Non-circular: load from beginning of state\n            state_ptrs = conv_state_ptr + conv_state_base + state_offs * stride_conv_state_tok\n        \n        state = tl.load(state_ptrs, mask=state_mask, other=0.0).to(tl.float32)\n        \n        # Load input x for this token\n        x_val = tl.load(x_ptr + x_base + tok * stride_x_token).to(tl.float32)\n        \n        # Compute convolution: sum(state[i] * w[i]) for i in 0..width-2, plus x * w[width-1]\n        w_state = tl.load(w_ptr + w_base + state_offs * stride_w_width, mask=state_mask, other=0.0).to(tl.float32)\n        w_last = tl.load(w_ptr + w_base + (KERNEL_WIDTH - 1) * stride_w_width).to(tl.float32)\n        \n        conv_sum = tl.sum(state * w_state) + x_val * w_last + bias\n        \n        # Apply activation\n        if SILU_ACTIVATION:\n            conv_sum = conv_sum * tl.sigmoid(conv_sum)\n        \n        # Store output\n        tl.store(o_ptr + o_base + tok * stride_o_token, conv_sum)\n        \n        # Update state: write new x to circular buffer position\n        if use_circular:\n            write_idx = cache_seqlen % state_len\n            tl.store(conv_state_ptr + conv_state_base + write_idx * stride_conv_state_tok, x_val)\n            cache_seqlen += 1\n        else:\n            # Non-circular: shift state left and append x at end\n            for i in range(KERNEL_WIDTH - 2):\n                next_val = tl.load(conv_state_ptr + conv_state_base + (i + 1) * stride_conv_state_tok)\n                tl.store(conv_state_ptr + conv_state_base + i * stride_conv_state_tok, next_val)\n            tl.store(conv_state_ptr + conv_state_base + (KERNEL_WIDTH - 2) * stride_conv_state_tok, x_val)",
        "causal_conv1d_update": "def causal_conv1d_update(\n    x: torch.Tensor,\n    conv_state: torch.Tensor,\n    weight: torch.Tensor,\n    bias: Optional[torch.Tensor] = None,\n    activation: Optional[str] = None,\n    cache_seqlens: Optional[torch.Tensor] = None,\n    conv_state_indices: Optional[torch.Tensor] = None,\n    pad_slot_id: int = PAD_SLOT_ID,\n    metadata=None,\n    validate_data=False,\n):\n    \"\"\"\n    x: (batch, dim, seqlen) or (batch, dim) for single token\n    conv_state: (batch or num_cache_lines, dim, state_len)\n    weight: (dim, width)\n    bias: (dim,)\n    cache_seqlens: (batch,) int32, for circular buffer\n    conv_state_indices: (batch,) int32, indices into conv_state\n    \"\"\"\n    # Ensure x is 3D\n    if x.dim() == 2:\n        x = x.unsqueeze(-1)\n    \n    batch, dim, seqlen = x.shape\n    _, _, state_len = conv_state.shape\n    _, width = weight.shape\n    \n    # Ensure contiguous\n    if x.stride(-1) != 1:\n        x = x.contiguous()\n    if weight.stride(-1) != 1:\n        weight = weight.contiguous()\n    if bias is not None and bias.stride(-1) != 1:\n        bias = bias.contiguous()\n    \n    # Check activation\n    silu_activation = activation in [\"silu\", \"swish\"]\n    \n    # Determine if using continuous batching\n    is_continuous_batching = conv_state_indices is not None\n    num_cache_lines = conv_state.shape[0] if is_continuous_batching else batch\n    \n    # Allocate output\n    out = torch.empty_like(x)\n    \n    # Compute block size for kernel width\n    BLOCK_N = triton.next_power_of_2(width)\n    NP2_STATELEN = triton.next_power_of_2(state_len)\n    \n    # Launch kernel with 2D grid (batch, dim)\n    grid = (batch, dim)\n    \n    _causal_conv1d_update_kernel[grid](\n        x,\n        weight,\n        bias,\n        conv_state,\n        cache_seqlens,\n        conv_state_indices,\n        out,\n        batch,\n        dim,\n        seqlen,\n        state_len,\n        num_cache_lines,\n        x.stride(0),\n        x.stride(1),\n        x.stride(2),\n        weight.stride(0),\n        weight.stride(1),\n        conv_state.stride(0),\n        conv_state.stride(1),\n        conv_state.stride(2),\n        out.stride(0),\n        out.stride(1),\n        out.stride(2),\n        pad_slot_id,\n        HAS_BIAS=bias is not None,\n        KERNEL_WIDTH=width,\n        SILU_ACTIVATION=silu_activation,\n        IS_CONTINUOUS_BATCHING=is_continuous_batching,\n        NP2_STATELEN=NP2_STATELEN,\n        USE_PAD_SLOT=is_continuous_batching,\n        BLOCK_N=BLOCK_N,\n    )\n    \n    # Squeeze if input was 2D\n    if x.dim() == 2 or seqlen == 1:\n        out = out.squeeze(-1)\n    \n    return out",
        "_causal_conv1d_fwd_kernel": "@triton.jit\ndef _causal_conv1d_fwd_kernel(\n    # Pointers to matrices\n    x_ptr,  # (dim, cu_seqlen)\n    w_ptr,  # (dim, width)\n    bias_ptr,\n    initial_states_ptr,  # conv_states_ptr\n    cache_indices_ptr,  # conv_state_indices_ptr\n    has_initial_states_ptr,\n    query_start_loc_ptr,\n    batch_ptr,\n    token_chunk_offset_ptr,\n    o_ptr,  # (dim, seqlen)\n    # Matrix dimensions\n    batch: tl.int32,\n    dim: tl.constexpr,\n    seqlen: tl.int32,\n    num_cache_lines: tl.constexpr,\n    # Strides\n    stride_x_seq: tl.constexpr,\n    stride_x_dim: tl.constexpr,\n    stride_x_token: tl.constexpr,\n    stride_w_dim: tl.constexpr,\n    stride_w_width: tl.constexpr,\n    stride_istate_seq: tl.constexpr,\n    stride_istate_dim: tl.constexpr,\n    stride_istate_token: tl.constexpr,\n    stride_o_seq: tl.constexpr,\n    stride_o_dim: tl.constexpr,\n    stride_o_token: tl.constexpr,\n    # others\n    pad_slot_id: tl.constexpr,\n    # Meta-parameters\n    HAS_BIAS: tl.constexpr,\n    KERNEL_WIDTH: tl.constexpr,\n    SILU_ACTIVATION: tl.constexpr,\n    HAS_INITIAL_STATES: tl.constexpr,\n    HAS_CACHE: tl.constexpr,\n    IS_CONTINUOUS_BATCHING: tl.constexpr,\n    USE_PAD_SLOT: tl.constexpr,\n    NP2_STATELEN: tl.constexpr,\n    DECODE_SEQLEN: tl.constexpr,\n    BLOCK_M: tl.constexpr,\n    BLOCK_N: tl.constexpr,\n):\n    # Each program handles a block of (dim, token) for one sequence\n    pid_m = tl.program_id(axis=0)  # dim block\n    pid_n = tl.program_id(axis=1)  # token block\n    pid_b = tl.program_id(axis=2)  # sequence\n    \n    # Get sequence boundaries from query_start_loc\n    query_start_loc_ptr += pid_b\n    seq_start = tl.load(query_start_loc_ptr).to(tl.int32)\n    seq_end = tl.load(query_start_loc_ptr + 1).to(tl.int32)\n    seq_len = seq_end - seq_start\n    \n    # Get cache index for this sequence\n    if HAS_CACHE:\n        cache_indices_ptr += pid_b\n        cache_idx = tl.load(cache_indices_ptr).to(tl.int32)\n        if USE_PAD_SLOT and cache_idx == pad_slot_id:\n            return\n    else:\n        cache_idx = pid_b\n    \n    # Check if this sequence has initial states\n    has_initial_state = True\n    if HAS_INITIAL_STATES:\n        has_initial_states_ptr += pid_b\n        has_initial_state = tl.load(has_initial_states_ptr).to(tl.int1)\n    \n    # Compute offsets\n    offs_m = pid_m * BLOCK_M + tl.arange(0, BLOCK_M)\n    offs_n = pid_n * BLOCK_N + tl.arange(0, BLOCK_N)\n    \n    mask_m = offs_m < dim\n    mask_n = offs_n < seq_len\n    \n    # Load weight for this dim block\n    w_offs = tl.arange(0, BLOCK_N)\n    w_mask = w_offs < KERNEL_WIDTH\n    w_ptr_base = w_ptr + offs_m[:, None] * stride_w_dim\n    w = tl.load(w_ptr_base + w_offs[None, :] * stride_w_width,\n                mask=mask_m[:, None] & w_mask[None, :], other=0.0).to(tl.float32)\n    \n    # Load bias\n    if HAS_BIAS:\n        bias = tl.load(bias_ptr + offs_m, mask=mask_m, other=0.0).to(tl.float32)\n    else:\n        bias = tl.zeros([BLOCK_M], dtype=tl.float32)\n    \n    # Load initial state if available\n    if HAS_INITIAL_STATES and has_initial_state:\n        state_offs = tl.arange(0, BLOCK_N)\n        state_mask = state_offs < (KERNEL_WIDTH - 1)\n        istate_ptr_base = initial_states_ptr + cache_idx * stride_istate_seq + offs_m[:, None] * stride_istate_dim\n        initial_state = tl.load(istate_ptr_base + state_offs[None, :] * stride_istate_token,\n                                mask=mask_m[:, None] & state_mask[None, :], other=0.0).to(tl.float32)\n    else:\n        initial_state = tl.zeros([BLOCK_M, KERNEL_WIDTH - 1], dtype=tl.float32)\n    \n    # Process each token in this block\n    for tok_idx in range(BLOCK_N):\n        if tok_idx >= seq_len:\n            break\n        \n        actual_tok = seq_start + tok_idx\n        \n        # Build convolution window: for causal conv, out[t] = sum_{i=0}^{width-1} x[t-i] * w[i]\n        # We need x[t-width+1:t+1], using initial_state for positions before seq_start\n        \n        # Load window elements\n        window = tl.zeros([BLOCK_M, KERNEL_WIDTH], dtype=tl.float32)\n        \n        for w_idx in range(KERNEL_WIDTH):\n            # Position relative to current token: we need x[tok_idx - (width - 1 - w_idx)]\n            rel_pos = tok_idx - (KERNEL_WIDTH - 1 - w_idx)\n            \n            if rel_pos < 0:\n                # Use initial state at position (width - 1 + rel_pos) = w_idx - (width - 1 - tok_idx)\n                state_idx = w_idx - (KERNEL_WIDTH - 1 - tok_idx)\n                if state_idx >= 0 and state_idx < (KERNEL_WIDTH - 1):\n                    init_val = tl.load(istate_ptr_base + state_idx * stride_istate_token,\n                                       mask=mask_m, other=0.0).to(tl.float32)\n                    # Store in window at column w_idx\n                    window = tl.where(\n                        (tl.arange(0, BLOCK_M)[:, None] < dim) & \n                        (tl.arange(0, KERNEL_WIDTH)[None, :] == w_idx),\n                        init_val[:, None], window)\n            else:\n                # Load from x\n                load_tok = seq_start + rel_pos\n                x_val = tl.load(x_ptr + offs_m * stride_x_dim + load_tok * stride_x_token,\n                               mask=mask_m, other=0.0).to(tl.float32)\n                # Store in window at column w_idx\n                window = tl.where(\n                    (tl.arange(0, BLOCK_M)[:, None] < dim) & \n                    (tl.arange(0, KERNEL_WIDTH)[None, :] == w_idx),\n                    x_val[:, None], window)\n        \n        # Compute convolution\n        out_val = tl.sum(window * w, axis=1) + bias\n        \n        # Apply activation\n        if SILU_ACTIVATION:\n            out_val = out_val * tl.sigmoid(out_val)\n        \n        # Store output\n        o_ptr_base = o_ptr + offs_m[:, None] * stride_o_dim\n        tl.store(o_ptr_base + actual_tok * stride_o_token, out_val[:, None], mask=mask_m[:, None])",
        "causal_conv1d_fn": "def causal_conv1d_fn(\n    x: torch.Tensor,\n    weight: torch.Tensor,\n    bias: Union[torch.Tensor, None],\n    conv_states: torch.Tensor,\n    query_start_loc: torch.Tensor,\n    cache_indices: Optional[torch.Tensor] = None,\n    has_initial_state: Optional[torch.Tensor] = None,\n    activation: Optional[str] = \"silu\",\n    pad_slot_id: int = PAD_SLOT_ID,\n    metadata=None,\n    validate_data=False,\n):\n    \"\"\"\n    x: (dim, total_length) for varlen or (batch, dim, seqlen)\n    weight: (dim, width)\n    bias: (dim,)\n    conv_states: (num_cache_lines, dim, state_len)\n    query_start_loc: (batch + 1,) cumulative sequence lengths\n    cache_indices: (batch,) indices into conv_states\n    has_initial_state: (batch,) bool tensor\n    \"\"\"\n    # Handle different input formats\n    if x.dim() == 3:\n        batch, dim, seqlen = x.shape\n        x = x.view(dim, -1)\n    else:\n        dim, total_length = x.shape\n    \n    _, width = weight.shape\n    \n    # Ensure contiguous\n    if x.stride(-1) != 1:\n        x = x.contiguous()\n    if weight.stride(-1) != 1:\n        weight = weight.contiguous()\n    if bias is not None and bias.stride(-1) != 1:\n        bias = bias.contiguous()\n    \n    # Check activation\n    silu_activation = activation in [\"silu\", \"swish\"]\n    \n    # Determine batch size from query_start_loc\n    batch = query_start_loc.shape[0] - 1\n    num_cache_lines = conv_states.shape[0]\n    state_len = conv_states.shape[2]\n    \n    # Output is in-place modification of x\n    out = x\n    \n    # Compute block sizes\n    BLOCK_M = 32\n    BLOCK_N = triton.next_power_of_2(width)\n    NP2_STATELEN = triton.next_power_of_2(state_len)\n    \n    # Launch kernel\n    grid = (triton.cdiv(dim, BLOCK_M), triton.cdiv(total_length, BLOCK_N), batch)\n    \n    _causal_conv1d_fwd_kernel[grid](\n        x,\n        weight,\n        bias,\n        conv_states,\n        cache_indices,\n        has_initial_state,\n        query_start_loc,\n        batch,\n        dim,\n        total_length,\n        num_cache_lines,\n        0,  # stride_x_seq\n        x.stride(0),\n        x.stride(1),\n        weight.stride(0),\n        weight.stride(1),\n        conv_states.stride(0),\n        conv_states.stride(1),\n        conv_states.stride(2),\n        out.stride(0),\n        out.stride(1),\n        out.stride(2) if out.dim() > 2 else 1,\n        pad_slot_id,\n        HAS_BIAS=bias is not None,\n        KERNEL_WIDTH=width,\n        SILU_ACTIVATION=silu_activation,\n        HAS_INITIAL_STATES=has_initial_state is not None,\n        HAS_CACHE=cache_indices is not None,\n        IS_CONTINUOUS_BATCHING=cache_indices is not None,\n        USE_PAD_SLOT=cache_indices is not None,\n        NP2_STATELEN=NP2_STATELEN,\n        DECODE_SEQLEN=1,\n        BLOCK_M=BLOCK_M,\n        BLOCK_N=BLOCK_N,\n    )\n    \n    return out"
    }
